//! The Vite dashboard, embedded at compile time.
//!
//! `ui/dist` is generated by `npm run build`; [`build`] turns it into this crate's
//! asset table. When the directory is absent the table is empty and [`is_built`]
//! reports `false`, so the gateway can fall back to its built-in shell instead of
//! failing the build for anyone without a node toolchain.

/// One served file.
pub struct Asset {
    /// Path relative to the dashboard root, e.g. `assets/index-abc123.js`.
    pub path: &'static str,
    pub bytes: &'static [u8],
    pub content_type: &'static str,
    /// Vite content-hashes these, so they can be cached forever.
    pub hashed: bool,
}

include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// `true` when a dashboard was embedded at build time.
pub fn is_built() -> bool {
    !ASSETS.is_empty()
}

/// Exact file lookup.
pub fn get(path: &str) -> Option<&'static Asset> {
    let trimmed = path.trim_start_matches('/');
    ASSETS.iter().find(|a| a.path == trimmed)
}

/// The SPA entry point, used for client-side routes like `/app/models`.
pub fn index() -> Option<&'static Asset> {
    get("index.html")
}
